import requests

BASE_URL = "https://api.socbench.example"

# Retrieve the top-rated products in every category.
response = requests.get(f"{BASE_URL}/products/top-rated")
response.raise_for_status()
categories = response.json()

# Collect unique product IDs and names from the top-rated results.
products = {}
for category in categories:
    for product in category.get("products", []):
        product_id = product.get("productId")
        if product_id:
            products[product_id] = product

# Fetch product descriptions and details using product search.
for product_id, product in products.items():
    name = product.get("productName", "")
    if name:
        search_response = requests.get(
            f"{BASE_URL}/products/search",
            params={"query": name, "page": 1, "size": 10},
        )
        search_response.raise_for_status()
        product["searchDetails"] = search_response.json()

# Retrieve available consumer trends and regional demand forecasts.
# The documented endpoints do not provide product-specific seasonal predictions
# or a forecast horizon, so request the available overview and forecast data.
trends_response = requests.get(f"{BASE_URL}/consumer-trends/overview")
trends_response.raise_for_status()
trends = trends_response.json()

forecast_response = requests.get(f"{BASE_URL}/inventory/demand-forecast")
forecast_response.raise_for_status()
demand_forecast = forecast_response.json()

# Retrieve prices for each product to allow retailer price comparisons.
prices_by_product = {}
for product_id in products:
    price_response = requests.get(
        f"{BASE_URL}/products/{product_id}/prices"
    )
    if price_response.status_code == 404:
        prices_by_product[product_id] = []
        continue
    price_response.raise_for_status()
    prices_by_product[product_id] = price_response.json()

# The documented API has no endpoint for submitting price updates or suggested
# changes. Report observed cross-retailer price differences without attempting
# an unsupported update request.
price_discrepancies = {}
for product_id, prices in prices_by_product.items():
    by_currency = {}
    for entry in prices:
        currency = entry.get("currency")
        price = entry.get("price")
        if currency is not None and isinstance(price, (int, float)):
            by_currency.setdefault(currency, []).append(entry)

    differences = {}
    for currency, entries in by_currency.items():
        if len(entries) > 1:
            values = [entry["price"] for entry in entries]
            if min(values) != max(values):
                differences[currency] = {
                    "minimum": min(values),
                    "maximum": max(values),
                    "retailers": entries,
                }
    if differences:
        price_discrepancies[product_id] = differences

result = {
    "topRatedProducts": categories,
    "productDetails": products,
    "consumerTrends": trends,
    "demandForecast": demand_forecast,
    "pricesByProduct": prices_by_product,
    "observedPriceDiscrepancies": price_discrepancies,
    "priceUpdateLimitation": (
        "No documented endpoint supports submitting price updates or suggested changes."
    ),
}
