import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()

# Retrieve the top-rated sustainable products across categories.
top_rated_response = session.get(f"{BASE_URL}/products/top-rated")
top_rated_response.raise_for_status()
top_rated_data = top_rated_response.json()

# Extract product IDs from common response shapes.
if isinstance(top_rated_data, list):
    products = top_rated_data
elif isinstance(top_rated_data, dict):
    products = (
        top_rated_data.get("products")
        or top_rated_data.get("results")
        or top_rated_data.get("data")
        or []
    )
else:
    products = []

product_ids = []
for product in products:
    if isinstance(product, dict):
        product_id = product.get("productId") or product.get("product_id") or product.get("id")
        if product_id is not None and product_id not in product_ids:
            product_ids.append(product_id)

# Fetch detailed product information and pricing for each top-rated product.
product_details = {}
product_prices = {}
for product_id in product_ids:
    detail_response = session.get(f"{BASE_URL}/products/{product_id}")
    detail_response.raise_for_status()
    product_details[product_id] = detail_response.json()

    prices_response = session.get(f"{BASE_URL}/products/{product_id}/prices")
    prices_response.raise_for_status()
    product_prices[product_id] = prices_response.json()

# Request seasonal predictions for the selected products over the next quarter.
predictions_response = session.post(
    f"{BASE_URL}/seasonal-trends/predictions",
    json={
        "product_ids": product_ids,
        "period": "next_quarter",
    },
)
predictions_response.raise_for_status()
seasonal_predictions = predictions_response.json()

# Compare retailer prices and request updates where discrepancies are observed.
price_update_requests = []
for product_id, pricing_data in product_prices.items():
    if isinstance(pricing_data, dict):
        retailers = (
            pricing_data.get("retailers")
            or pricing_data.get("prices")
            or pricing_data.get("data")
            or []
        )
    elif isinstance(pricing_data, list):
        retailers = pricing_data
    else:
        retailers = []

    retailer_prices = []
    for entry in retailers:
        if isinstance(entry, dict):
            price = entry.get("price")
            retailer_id = entry.get("retailerId") or entry.get("retailer_id")
            if isinstance(price, (int, float)):
                retailer_prices.append((retailer_id, price, entry))

    if len(retailer_prices) < 2:
        continue

    values = [item[1] for item in retailer_prices]
    if min(values) == max(values):
        continue

    suggested_price = round(sum(values) / len(values), 2)
    for retailer_id, current_price, entry in retailer_prices:
        if current_price != suggested_price:
            payload = {
                "product_id": product_id,
                "retailer_id": retailer_id,
                "current_price": current_price,
                "suggested_price": suggested_price,
                "reason": "Price discrepancy across retailers",
            }
            update_response = session.post(
                f"{BASE_URL}/request_update",
                json=payload,
            )
            update_response.raise_for_status()
            price_update_requests.append(update_response.json())

result = {
    "top_rated_products": products,
    "product_details": product_details,
    "seasonal_predictions": seasonal_predictions,
    "price_update_requests": price_update_requests,
}

